//! 🧫️ Registered native formats preserve original custody and match the shared independent oracle.
use super::*;
use semio_framework_os_kernel::io::io_mechanism::{io_register,io_begin_owned_serialization};
use semio_framework_job::{OperationId,Generation,StepBudget,root_cancel_token};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn clock()->Option<u64>{Some(0)}
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn handoffs()->serde_json::Value{serde_json::from_str(include_str!("../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🚪️io/📤️serialization/📦️owned/🧫️fixtures/🔣️.json")).unwrap()}
fn terminal_grant(row:&serde_json::Value)->RetainedCloneGrant{let g=&row["grant"];RetainedCloneGrant{maximum_items:g["items"].as_u64().unwrap()as usize,maximum_copy_bytes:g["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:g["release"].as_u64().unwrap()as usize,maximum_depth:g["depth"].as_u64().unwrap()as usize}}
fn target(format:&str)->ArtifactDialect{let(kind,standard)=match format{"png"=>("s.stdio.png","1.2"),"svg"=>("s.stdio.svg","1.1"),_=>("s.stdio.pdf","1.4")};ArtifactDialect{artifact_kind:kind.into(),standard:standard.into(),subset:"*".into()}}
fn document()->DrawingSnapshot{let rows:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/🎬️scene/📋️prepare/🧫️fixtures/🔣️.json")).unwrap();let source=rows.as_array().unwrap().iter().find(|row|row["name"]=="rectangle").unwrap();let mut doc:DrawingSnapshot=serde_json::from_value(source["document"].clone()).unwrap();doc.artboard=Some(crate::DrawingArtboard{width:2.0,height:1.0});doc}
fn pump_returns(issuer:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>,active:&mut Option<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>){let demand=if let Some(owner)=active.as_ref(){let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();store::artifact_retirement_box_demands(owner,if copy>0{copy}else{release}).unwrap()}else{issuer.returned_snapshot_read_retirement_demand().unwrap()};if active.is_none()&&issuer.returned_snapshot_read_count()==0{return;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(progress,physical)=observe(||{if active.is_some(){store::artifact_retirement_box_close_step(active,grant).unwrap().progress()}else{let(owner,progress)=issuer.take_returned_snapshot_read_retirement(grant).unwrap();*active=owner;progress}});assert!(progress.fits(grant));assert_eq!(physical.requested_bytes,progress.retained_capacity_bytes);assert_eq!(physical.released_bytes,progress.released_bytes);}
fn close_job(mut job:Box<dyn OwnedSerializerJob>,issuer:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>){let mut returned=None;job.begin_close();for _ in 0..2_000_000{pump_returns(issuer,&mut returned);if job.terminal_is_empty(){break;}let copy=job.next_close_copy_byte_demand().unwrap();let release=job.next_close_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:job.next_close_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:job.next_close_depth_demand().unwrap()};for axis in ["items","copy","capacity","release","depth"]{let mut denied=grant;match axis{"items"=>denied.maximum_items=0,"copy" if copy>0=>denied.maximum_copy_bytes-=1,"capacity" if grant.maximum_capacity_bytes>0=>denied.maximum_capacity_bytes-=1,"release" if release>0=>denied.maximum_release_bytes-=1,"depth" if grant.maximum_depth>0=>denied.maximum_depth-=1,_=>continue}let(step,physical)=observe(||job.close_step(denied));assert!(!physical.overflowed);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(matches!(step,InteractiveJobCloseStep::Blocked|InteractiveJobCloseStep::Refused(_))||matches!(step,InteractiveJobCloseStep::Pending{progress}if progress==Default::default()));}let(step,physical)=observe(||job.close_step(grant));let progress=match step{InteractiveJobCloseStep::Pending{progress}|InteractiveJobCloseStep::Complete{progress}=>progress,other=>panic!("Exact serializer close refused: {other:?}")};assert!(progress.fits(grant));assert!(!physical.overflowed);assert_eq!(physical.requested_bytes,progress.retained_capacity_bytes);assert_eq!(physical.released_bytes,progress.released_bytes);}assert!(job.terminal_is_empty());for _ in 0..100000{if returned.is_none()&&issuer.returned_snapshot_read_count()==0{break;}pump_returns(issuer,&mut returned);}assert!(returned.is_none()&&issuer.returned_snapshot_read_count()==0);let frame=job.terminal_frame_release_bytes().unwrap();let(_,physical)=observe(||drop(job));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,frame));}
fn close_owned<T:semio_framework_value::RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));for _ in 0..2_000_000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(step,physical)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(physical.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(physical.released_bytes,step.progress().released_bytes);}assert!(owner.terminal_is_empty());let(_,physical)=observe(||drop(owner));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));}
#[semio_framework_async_macros::async_test]
async fn drawing_owned_serializer_original_routes(){
 io_register(crate::standards::v1::subsets::any::io::io().entries).unwrap();let contract=corpus();
 for format in contract["formats"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()){
  for fuel in contract["workGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()){
   let mut issuer=store::ArtifactStore::new(store::create_document_envelope::<DrawingSnapshot,crate::op::DrawingMutation>("drawing.drawing","captured-native-export",document(),None),protocol::ActorId(protocol::LOCAL_ACTOR_ID.into())).await.unwrap();issuer.install_document_store_owners_exact(crate::spr::drawing_document_store_owners());let generation=issuer.generation().0;let revision=issuer.content_revision_now();let read=issuer.snapshot_read().unwrap();let original=read.get()as*const DrawingSnapshot;let mut request=OwnedSerializerRequest{source:read.into_erased(),route:(crate::DRAWING_DIALECT.into(),target(format)),generation,revision,options:DslValue::Object(vec![("width".into(),DslValue::uint(2)),("height".into(),DslValue::uint(1)),("transparent".into(),DslValue::Bool(true))]),children:None};let options=request.options.as_object().unwrap().as_ptr();let route=request.route.1.artifact_kind.as_ptr();let demand=serializer_demand(&request,match format{"png"=>"png","svg"=>"svg",_=>"pdf"}).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:demand.capacity_bytes,maximum_depth:demand.depth,..Default::default()};
   for axis in contract["deniedBirth"].as_array().unwrap(){let mut denied=grant;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"capacity"=>denied.maximum_capacity_bytes-=1,_=>denied.maximum_depth=0}let(result,physical)=observe(||io_begin_owned_serialization(request,denied));let refusal=match result{Err(refusal)=>refusal,Ok(_)=>panic!("Denied constructor admitted")};assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(refusal.progress,Default::default());request=refusal.request;assert_eq!(request.source.get::<DrawingSnapshot>().unwrap()as*const DrawingSnapshot,original);assert_eq!(request.options.as_object().unwrap().as_ptr(),options);assert_eq!(request.route.1.artifact_kind.as_ptr(),route);}
   let(result,physical)=observe(||io_begin_owned_serialization(request,grant));let admission=match result{Ok(admission)=>admission,Err(refusal)=>panic!("Native route refused: {}",refusal.error)};assert_eq!(physical.requested_bytes,admission.progress.retained_capacity_bytes);assert_eq!(physical.released_bytes,0);assert_eq!(admission.progress.retained_capacity_bytes,demand.capacity_bytes);let mut job=admission.job;let token=root_cancel_token();let mut sequence=0;let mut zero=StepContext::new(OperationId(17),Generation(generation),StepBudget::new(0,u64::MAX),token.clone(),clock,&mut sequence);let(outcome,physical)=observe(||job.step(&mut zero));assert_eq!(outcome,StepOutcome::Yield);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));let mut completed=false;for _ in 0..1_000_000{let mut cx=StepContext::new(OperationId(17),Generation(generation),StepBudget::new(fuel,u64::MAX),token.clone(),clock,&mut sequence);match job.step(&mut cx){StepOutcome::Yield=>{},StepOutcome::Complete(_)=>{completed=true;break;},other=>panic!("Native serializer failed: {other:?} {}",job.fault().map_or("",|fault|fault.message.as_str()))}assert!(cx.fuel_remaining()<=fuel);}assert!(completed);let output=job.output().unwrap();let page=output.page(0).unwrap().as_ptr();for row in handoffs()["terminalHandoffs"].as_array().unwrap().iter().filter(|row|row["kind"]=="output"&&row["current"]==true&&row["finished"]==true&&row["available"]==true&&row["cancelled"]==false&&row["accepted"]==false){let denied=terminal_grant(row);let(result,physical)=observe(||job.take_output(denied));assert!(result.is_err());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(job.output().unwrap().page(0).unwrap().as_ptr(),page);}let(result,physical)=observe(||job.take_output(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}));let handoff=result.unwrap().unwrap();assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(handoff.progress,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(handoff.output.page(0).unwrap().as_ptr(),page);assert!(job.output().is_none());let bytes=(0..handoff.output.page_count()).flat_map(|index|handoff.output.page(index).unwrap().iter().copied()).collect::<Vec<_>>();
   if format=="png"{let decoder=png::Decoder::new(std::io::Cursor::new(&bytes));let mut reader=decoder.read_info().unwrap();let mut pixels=vec![0;reader.output_buffer_size()];let info=reader.next_frame(&mut pixels).unwrap();assert_eq!((info.width,info.height),(2,1));assert_eq!(pixels[..info.buffer_size()],contract["expected"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect::<Vec<_>>());}
   if let Some(directory)=std::env::var_os("SEMIO_TEST_ARTIFACT_DIR"){let directory=std::path::PathBuf::from(directory);std::fs::create_dir_all(&directory).unwrap();std::fs::write(directory.join(format!("{format}-{fuel}.{format}")),&bytes).unwrap();}close_job(job,&mut issuer);close_owned(handoff.output);if fuel==1{for stop in contract["cancelTurns"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()){let read=issuer.snapshot_read().unwrap();let request=OwnedSerializerRequest{source:read.into_erased(),route:(crate::DRAWING_DIALECT.into(),target(format)),generation,revision,options:DslValue::Null,children:None};let mut cancelled=match io_begin_owned_serialization(request,grant){Ok(admission)=>admission.job,Err(refusal)=>panic!("{}",refusal.error)};let token=root_cancel_token();for _ in 0..stop{let mut cx=StepContext::new(OperationId(18),Generation(generation),StepBudget::new(1,u64::MAX),token.clone(),clock,&mut sequence);if cancelled.step(&mut cx).is_terminal(){break;}}if stop==40{for _ in 0..1_000_000{let mut cx=StepContext::new(OperationId(18),Generation(generation),StepBudget::new(4096,u64::MAX),token.clone(),clock,&mut sequence);if cancelled.output().is_some(){break;}assert!(!matches!(cancelled.step(&mut cx),StepOutcome::Fault(_)));}assert!(cancelled.output().is_some());}token.cancel().await;let mut cx=StepContext::new(OperationId(18),Generation(generation),StepBudget::new(1,u64::MAX),token,clock,&mut sequence);let(outcome,physical)=observe(||cancelled.step(&mut cx));assert_eq!(outcome,StepOutcome::Cancelled);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cancelled.output().is_none());assert!(cancelled.take_output(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}).is_err());close_job(cancelled,&mut issuer);eprintln!("[DEBUG] Registered original {format} cancellation stop={stop}: partial/completed unpublished output withheld and original owners physically closed");}}
   if fuel==1&&format=="png"{let request=OwnedSerializerRequest{source:issuer.snapshot_read().unwrap().into_erased(),route:(crate::DRAWING_DIALECT.into(),target(format)),generation,revision,options:DslValue::Object(vec![("width".into(),DslValue::uint(contract["fault"]["width"].as_u64().unwrap())),("height".into(),DslValue::uint(contract["fault"]["height"].as_u64().unwrap()))]),children:None};let mut failed=match io_begin_owned_serialization(request,grant){Ok(admission)=>admission.job,Err(refusal)=>panic!("{}",refusal.error)};let token=root_cancel_token();let mut observed=false;for _ in 0..10{let mut cx=StepContext::new(OperationId(19),Generation(generation),StepBudget::new(1,u64::MAX),token.clone(),clock,&mut sequence);if matches!(failed.step(&mut cx),StepOutcome::Fault(_)){observed=true;break;}}assert!(observed);let message=failed.fault().unwrap().message.as_ptr();assert!(failed.output().is_none());for row in handoffs()["terminalHandoffs"].as_array().unwrap().iter().filter(|row|row["kind"]=="fault"&&row["current"]==true&&row["finished"]==true&&row["available"]==true&&row["cancelled"]==false&&row["accepted"]==false){let denied=terminal_grant(row);let(result,physical)=observe(||failed.take_fault(denied));assert!(result.is_err());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(failed.fault().unwrap().message.as_ptr(),message);}let(result,physical)=observe(||failed.take_fault(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}));let handoff=result.unwrap().unwrap();assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(handoff.fault.message.as_ptr(),message);assert_eq!(handoff.progress,RetainedCloneProgress{copied_items:1,..Default::default()});assert!(failed.fault().is_none()&&failed.output().is_none());close_job(failed,&mut issuer);close_owned(handoff.fault);eprintln!("[DEBUG] Registered original PNG pixel-limit Fault conserved exact diagnostic string pointer on denied and funded handoff, then physical close");}for _ in 0..1_000_000{if issuer.close_owned_terminal_is_empty(){break;}let demand=issuer.close_owned_demands(4096).unwrap();issuer.close_owned_step(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}).unwrap();}assert!(issuer.close_owned_terminal_is_empty());eprintln!("[DEBUG] Registered original {format} route fuel={fuel}: exact source/metadata identity, funded frame, original output handoff and physical close");
  }
 }
}
